import os
import json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
sessions_file = os.path.join(d, '..', '..', 'sessions', os.path.basename(d) + '.jsonl')

with open(sessions_file) as f:
    lines = f.readlines()

# Find all message types
types_seen = {}
for line in lines:
    if '"type":"message"' in line:
        try:
            msg = json.loads(line)
            role = msg.get('message', {}).get('role', 'unknown')
            types_seen[role] = types_seen.get(role, 0) + 1
        except:
            pass

print("Message types:")
for t, c in sorted(types_seen.items()):
    print(f"  {t}: {c}")

# Look for any role other than "assistant" or "toolResult"
for t in ['game', 'system', 'model']:
    print(f"\nSearching for role='{t}' message...")
    for line in lines:
        if f'"role":"{t}"' in line or f'"role": "{t}"' in line:
            print(f"Found: {line[:200]}")

